easy_widgets.BannerWidget.css:
.banner-widget {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 140px;
    outline: 1px solid rgb(0,0,0,0.3);
    border-width: 0;
    overflow: hidden;
    border-radius: 0;
    box-shadow: none;
    margin-bottom: 30px;
    position: relative;
}
.banner-widget.border-disabled {
    outline: none;
}
.banner-widget:last-child {
    margin-bottom: 0;
}
.banner-background {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    z-index: 0;
}

.banner-body {
    display: flex;  
    flex: 1;
    min-height: 0;
    height: 140px;
    position: relative;
    z-index: 1;
}

/* Text mode styles */
.banner-body.mode-text {
    justify-content: flex-start;
    align-items: flex-start;
}

.banner-body.mode-text .banner-text {
    flex: 1; 
    padding: 26px 30px 30px;
    font-size: 16px;
    font-family: 'Source Sans 3', sans-serif;
    font-weight: 300;
    line-height: 22px;
    overflow: hidden;
}
.banner-body.mode-text .banner-text h3 {
    font-size: 18px;
    font-family: 'Source Sans 3', sans-serif;
    font-weight: 700;
    line-height: 22px;
    overflow: hidden;
    margin-top: 0;
    margin-bottom: 3px;
}
.banner-body.mode-text .banner-text p {
    font-size: 14px;
    font-family: 'Source Sans 3', sans-serif;
    font-weight: 300;
    line-height: 17px;
    overflow: hidden;
    margin-top: 0;
    margin-bottom: 0;
}    
.banner-body.mode-text .banner-images {
    display: flex;
    align-items: top;
    justify-content: right;
    padding: 0px; 
}

/* Header mode styles */
.banner-body.mode-header {
    justify-content: center;
    align-items: center;
}

.banner-body.mode-header .banner-text {
    width: 100%;
    padding: 30px;
    text-align: center;
    font-size: 36px;
    font-family: 'Source Sans 3', sans-serif;
    font-weight: 500;
    line-height: 32px;
    overflow: hidden;
    margin-top: 0;
    margin-bottom: 0;
}

/* Individual image styling - square (default) */
.banner-image {
    width: 140px;
    height: 140px;
    object-fit: cover;
    border: 5px solid white;
}

.banner-widget.border-disabled {
    border: none;
}

/* Rectangle image styling */
.banner-body.image-size-rectangle .banner-image {
    width: 280px;
    height: 140px;
    border: 5px solid white;
}

/* Responsive behavior */
@media (max-width: 768px) {
    .banner-body.mode-text {
        flex-direction: column;
    }
}

easy_widgets.BioWidget.css:
.bio-widget {
    display: block;
    width: 100%;
    height: auto;
    margin-bottom: 30px;
}

.bio-widget__container {
    width: 100%;
}

/* Column layout - side by side */
.bio-widget--column .bio-widget__container {
    display: flex;
    gap: 30px;
    align-items: flex-start;
}

.bio-widget--column .bio-widget__image {
    flex: 0 0 33.33%;
    max-width: 33.33%;
}

.bio-widget--column .bio-widget__text {
    flex: 1;
    min-width: 0;
}

/* Flow layout - text wraps around image */
.bio-widget--flow .bio-widget__container {
    display: block;
}

.bio-widget--flow .bio-widget__image {
    float: left;
    width: 33.33%;
    max-width: 400px;
    margin: 0 30px 30px 0;
}

.bio-widget--flow .bio-widget__text {
    display: block;
}

/* Clear float after flow layout */
.bio-widget--flow .bio-widget__container::after {
    content: "";
    display: table;
    clear: both;
}

/* Image styling */
.bio-widget__image img {
    width: 100%;
    height: auto;
}   

/* Responsive - stack on mobile */
@media (max-width: 768px) {
    .bio-widget--column .bio-widget__container {
        flex-direction: column;
    }

    .bio-widget--column .bio-widget__image {
        flex: 0 0 auto;
        max-width: 100%;
        margin-bottom: 40px;
    }

    .bio-widget--flow .bio-widget__image {
        float: none;
        width: 100%;
        max-width: 100%;
        margin: 0 0 30px 0;
    }
}

